"""Generate a portable offline dashboard; escape all catalog/source values."""
from html import escape
from decimal import Decimal

def h(v):return escape(str(v),quote=True)
def num(v):return '—' if v is None else f'{v:,}'
def usd(v):return '—' if v is None else ('−' if v<0 else '')+'$'+f'{abs(v):,.0f}'
def percent(v):return '—' if v is None else str(v)+'%'
def table(columns,rows):
    if not rows:return '<p class="empty">No matching observations.</p>'
    return '<div class="scroll"><table><thead><tr>'+''.join('<th scope="col">'+h(label)+'</th>' for label,_,_ in columns)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+h(fmt(r[k]))+'</td>' for _,k,fmt in columns)+'</tr>' for r in rows)+'</tbody></table></div>'

def render(r):
    o=r['overview'][0];n=o['started'];done=o['completed'];cohort=r['filters']['cohort'];b=r['budget'][0];title={'demo':'Synthetic demo','internal':'Internal tests','playtest':'Labeled human playtests'}[cohort]
    sections=[]
    def section(title,description,content):sections.append(f'<section><h2>{h(title)}</h2><p>{h(description)}</p>{content}</section>')
    bars=''.join(f'<div class="stage"><span>{h(s["label"])}</span><meter min="0" max="{max(1,n)}" value="{s["reached"]}" aria-label="{h(s["label"])}"></meter><strong>{s["reached"]} / {n}</strong></div>' for s in r['funnel']) if n else '<p class="empty">No drafts started within these filters.</p>'
    section('Where do drafts stop?','Each stage counts distinct drafts that reached it. All percentages use starts in this cohort.',bars+'<p><a href="#trace">Trace the completion numerator and denominator ↓</a></p>'+table([('Picks at last observation','picks_made',num),('Explicit abandon','explicitly_abandoned',num),('Still unfinished','still_unfinished',num)],r['stops']))
    section('Time between committed picks','Elapsed wall-clock seconds from the start or previous initial pick. Includes rerolls and time away; this is not screen dwell time.',table([('Role','slot',str),('Measured picks','measured_picks',num),('Median seconds','median_seconds',num),('Negative intervals omitted','clock_reversals',num)],r['rounds']))
    section('Genre choices','Share of all starts, including unfinished productions.',table([('Genre','genre',str),('Starts','starts',num),('Share','share_pct',percent),('Released','official_releases',num)],r['genres']))
    section('Who gets picked?','Picks / selectable initial-role offers issued for this person and slot. Recasts are excluded from pick rate. Score and profit use final rosters of official releases, including confirmed recasts; sample sizes matter and associations do not establish cause.',table([('Talent','name',str),('Slot','slot',str),('Offers','selectable_offers',num),('Picks','selections',num),('Pick rate','pick_pct',percent),('Official films','official_films',num),('Mean score','avg_score',num),('Mean profit','avg_profit_usd',usd)],r['talent']))
    section('Where did the budget go?',f'Final rosters of {b["official_films"]} official releases only. Marketing is outside the original budget. Utilization is total fees divided by total talent allowance, not an average of individual percentages.',f'<p><b>{usd(b["committed_talent"])}</b> talent fees · <b>{usd(b["unused_allowance"])}</b> unused hiring allowance · <b>{usd(b["reserved_production"])}</b> production reserve · <b>{percent(b["utilization_pct"])}</b> hiring utilization.</p>'+table([('Slot','slot',str),('Released films','released_films',num),('Total final fees','total_fees',usd),('Mean final fee','mean_fee',usd)],r['allocations']))
    section('What is in this sample?','A session is one captured draft, not a unique player. An unfinished draft is not an abandonment. Imported catalogs are not proof of human activity; cohort labels are explicit.',f'<p>{o["replay_starts"]} explicit replay starts · {o["confirmed_recasts"]} confirmed recasts · {o["comparisons"]} distinct hypothetical comparisons (excluded from release outcomes) · {o["fixture_sessions"]} fixture-catalog sessions.</p>'+table([('Catalog','catalog',str),('Rules','rules',str),('Scoring','scoring',str),('Simulation','simulation',str),('Starts','starts',num)],r['versions']))
    trace=table([('Session key','session_key',str),('Start evidence','start_event',str),('Official release evidence','release_event',lambda v:v or 'Not observed'),('Official score','official_score',num)],r['trace'])
    sections.append('<section id="trace"><h2>Trace a dashboard number</h2><p>One row per start. Count the nonempty release IDs for the numerator. Match the complete evidence keys to the events table in your local SQLite file.</p><details><summary>Inspect all '+str(n)+' trace rows</summary>'+trace+'</details></section>')
    filt=' · '.join(h(k)+': '+h(v) for k,v in r['filters'].items());rate='—' if n==0 else f'{100*done/n:.1f}%'
    style='''*{box-sizing:border-box}body{margin:0;background:#f5f1e8;color:#172922;font:16px/1.5 system-ui,sans-serif}header{background:#173b32;color:#fff3dd;padding:38px max(6vw,24px) 44px;border-bottom:5px solid #cc943b}header small{letter-spacing:.16em;color:#f0c16f;text-transform:uppercase}h1{font:clamp(2rem,5vw,4rem)/1.08 Georgia,serif;margin:.4em 0}h2{font:1.7rem Georgia,serif;margin:0 0 .5em}main{max-width:1180px;margin:auto;padding:24px}section,.kpi{background:#fffdf8;border:1px solid #cfc8b8;border-radius:8px;padding:22px;margin:16px 0}p{max-width:90ch}.filters{overflow-wrap:anywhere;font-size:.88rem}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:12px}.kpi{margin:0}.kpi b{display:block;font-size:2rem;color:#164d3a}.stage{display:grid;grid-template-columns:6em minmax(20px,1fr) 5em;gap:10px;align-items:center;padding:.25em 0}.stage strong{text-align:right}meter{width:100%;height:18px;accent-color:#297456}a{color:#135c42}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-variant-numeric:tabular-nums}th,td{padding:.55em .7em;text-align:left;border-bottom:1px solid #e4ddcb}th{background:#e9e9de;font-size:.82em}summary{cursor:pointer}#trace td{font-family:monospace;overflow-wrap:anywhere;min-width:11em}.empty{font-style:italic;color:#535c55}@media(max-width:560px){main{padding:12px}section,.kpi{padding:14px}.stage{grid-template-columns:4.5em minmax(20px,1fr) 4em}.grid{grid-template-columns:1fr 1fr}header{padding:24px 16px}}'''
    notice='Invented sessions for practicing SQL. No real player behavior is represented.' if cohort=='demo' else 'Locally captured observations only. Cohort classification is supplied by the operator; this is not population-wide telemetry.'
    return '<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CineDraft • Gameplay analytics</title><style>'+style+'</style><header><small>CineDraft / internal analysis / Phase 12</small><h1>Gameplay analytics</h1><strong>'+h(title)+'</strong><p>'+notice+'</p></header><main><p class="filters">'+filt+'</p><div class="grid">'+''.join('<div class="kpi">'+h(k)+'<b>'+h(v)+'</b></div>' for k,v in [('Draft starts',n),('Official releases',done),('Completion',rate),('Explicit abandons',o['abandoned'])])+'</div>'+''.join(sections)+'</main></html>'
